88	// concurrent use on a shared Parser.
89	func (p *Parser) ParseConfigFiles(args []string, paths []string, environ map[string]string) (*Result, error) {
90		if len(paths) == 0 {
91			return p.ParseWithSources(args, nil, environ)
92		}
93	
94		// Phase 1: read and validate every file. Nothing is merged until all
95		// of them have succeeded, so a failure cannot leak a partial result.
96		files := make([]map[string][]string, len(paths))
97		for i, path := range paths {
98			entries, err := loadConfigFile(path)
99			if err != nil {
100				return nil, err
101			}
102			files[i] = entries
103		}
104	
105		// Phase 2: merge in ascending priority order. A non-empty group
106		// replaces the lower-priority group wholesale; an empty group (null
107		// or empty array) removes the key from the config layer entirely.
108		merged := make(map[string][]string)
