123	
124	// loadConfigFile reads and validates one configuration file, returning
125	// its top-level entries as raw value groups. A key mapped to an empty
126	// slice was explicitly cleared (null or empty array).
127	func loadConfigFile(path string) (map[string][]string, error) {
128		var parse func([]byte) (map[string][]string, error)
129		switch strings.ToLower(filepath.Ext(path)) {
130		case ".json":
131			parse = parseJSONConfig
132		case ".yaml", ".yml":
133			parse = parseYAMLConfig
134		default:
135			return nil, &ConfigError{Path: path, kind: ErrUnsupportedConfigFormat,
136				msg: fmt.Sprintf("command: unsupported config file format %q", path)}
137		}
138	
139		data, err := os.ReadFile(path)
140		if err != nil {
141			return nil, &ConfigError{Path: path, kind: ErrConfigIO,
142				msg: fmt.Sprintf("command: cannot read config file %q: %v", path, err)}
143		}
144	
145		entries, err := parse(data)
146		if err != nil {
147			return nil, &ConfigError{Path: path, kind: ErrInvalidConfig,
148				msg: fmt.Sprintf("command: invalid config file %q: %v", path, err)}
149		}
150		return entries, nil
151	}
152	
153	// parseJSONConfig decodes one JSON configuration document. The decoder is
154	// driven token by token so that duplicated top-level keys and disallowed
155	// value shapes are reported instead of silently accepted.
156	func parseJSONConfig(data []byte) (map[string][]string, error) {
157		dec := json.NewDecoder(bytes.NewReader(data))
158		dec.UseNumber()
159	
160		tok, err := dec.Token()
161		if err != nil {
162			return nil, fmt.Errorf("syntax error: %v", err)
163		}
164		if d, ok := tok.(json.Delim); !ok || d != '{' {
165			return nil, errors.New("top level must be an object")
166		}
167	
168		entries := make(map[string][]string)
169		for dec.More() {
170			ktok, err := dec.Token()
171			if err != nil {
172				return nil, fmt.Errorf("syntax error: %v", err)
173			}
174			key, ok := ktok.(string)
175			if !ok {
176				return nil, fmt.Errorf("expected object key, got %v", ktok)
177			}
178			if _, dup := entries[key]; dup {
179				return nil, fmt.Errorf("duplicate top-level key %q", key)
180			}
181	
182			vtok, err := dec.Token()
183			if err != nil {
184				return nil, fmt.Errorf("syntax error: %v", err)
185			}
186			if d, ok := vtok.(json.Delim); ok {
187				if d != '[' {
188					return nil, fmt.Errorf("key %q: object values are not allowed", key)
189				}
190				values, err := jsonArray(dec, key)
191				if err != nil {
192					return nil, err
193				}
194				entries[key] = values
195				continue
196			}
197			raw, isNull, err := jsonScalar(vtok)
198			if err != nil {
199				return nil, fmt.Errorf("key %q: %v", key, err)
200			}
201			if isNull {
202				entries[key] = nil
203				continue
204			}
205			entries[key] = []string{raw}
206		}
207		if _, err := dec.Token(); err != nil {
208			return nil, fmt.Errorf("syntax error: %v", err)
209		}
210		if _, err := dec.Token(); err != io.EOF {
211			return nil, errors.New("unexpected content after top-level object")
212		}
213		return entries, nil
214	}
215	
216	// jsonArray consumes one JSON array of scalars, including the closing
217	// delimiter. Nested arrays, objects and null elements are rejected.
218	func jsonArray(dec *json.Decoder, key string) ([]string, error) {
219		values := []string{}
220		for dec.More() {
221			tok, err := dec.Token()
222			if err != nil {
223				return nil, fmt.Errorf("syntax error: %v", err)
224			}
225			raw, isNull, err := jsonScalar(tok)
226			if err != nil {
227				return nil, fmt.Errorf("key %q: %v", key, err)
228			}
229			if isNull {
230				return nil, fmt.Errorf("key %q: null array elements are not allowed", key)
231			}
232			values = append(values, raw)
233		}
234		if _, err := dec.Token(); err != nil {
235			return nil, fmt.Errorf("syntax error: %v", err)
236		}
237		return values, nil
238	}
239	
240	// jsonScalar renders one JSON scalar token as a raw config value. A nil
241	// token is JSON null, reported via isNull; anything else (a delimiter) is
242	// a structural error.
243	func jsonScalar(tok any) (raw string, isNull bool, err error) {
244		switch v := tok.(type) {
245		case nil:
246			return "", true, nil
247		case string:
248			return v, false, nil
249		case bool:
250			return strconv.FormatBool(v), false, nil
251		case json.Number:
252			text, err := decimalText(string(v))
253			if err != nil {
254				return "", false, fmt.Errorf("invalid number %q", string(v))
255			}
256			return text, false, nil
257		default:
258			return "", false, errors.New("nested arrays and objects are not allowed")
259		}
260	}
261	
262	// parseYAMLConfig decodes one YAML configuration document into the same
263	// entry shape as parseJSONConfig. An empty file yields an empty object.
264	func parseYAMLConfig(data []byte) (map[string][]string, error) {
265		dec := yaml.NewDecoder(bytes.NewReader(data))
266		var doc yaml.Node
267		if err := dec.Decode(&doc); err != nil {
268			if err == io.EOF {
269				return map[string][]string{}, nil
270			}
271			return nil, fmt.Errorf("syntax error: %v", err)
272		}
273		var extra yaml.Node
274		if err := dec.Decode(&extra); err != io.EOF {
275			return nil, errors.New("multiple documents are not allowed")
276		}
277	
278		root := &doc
279		if root.Kind == yaml.DocumentNode {
280			root = root.Content[0]
281		}
282		if root.Kind != yaml.MappingNode {
283			return nil, errors.New("top level must be an object")
284		}
285	
286		entries := make(map[string][]string)
287		for i := 0; i < len(root.Content); i += 2 {
288			kn, vn := root.Content[i], resolveAlias(root.Content[i+1])
289			if kn.Kind != yaml.ScalarNode {
290				return nil, errors.New("non-scalar top-level keys are not allowed")
291			}
292			key := kn.Value
293			if _, dup := entries[key]; dup {
294				return nil, fmt.Errorf("duplicate top-level key %q", key)
295			}
296	
297			switch vn.Kind {
298			case yaml.ScalarNode:
299				raw, isNull, err := yamlScalar(vn)
300				if err != nil {
301					return nil, fmt.Errorf("key %q: %v", key, err)
302				}
303				if isNull {
304					entries[key] = nil
305					continue
306				}
307				entries[key] = []string{raw}
308			case yaml.SequenceNode:
309				values := []string{}
310				for _, item := range vn.Content {
311					item = resolveAlias(item)
312					if item.Kind != yaml.ScalarNode {
313						return nil, fmt.Errorf("key %q: nested arrays and objects are not allowed", key)
314					}
315					raw, isNull, err := yamlScalar(item)
316					if err != nil {
317						return nil, fmt.Errorf("key %q: %v", key, err)
318					}
319					if isNull {
320						return nil, fmt.Errorf("key %q: null array elements are not allowed", key)
321					}
322					values = append(values, raw)
323				}
324				entries[key] = values
325			default:
326				return nil, fmt.Errorf("key %q: object values are not allowed", key)
327			}
328		}
329		return entries, nil
330	}
331	
332	// resolveAlias follows a YAML alias to its target node.
333	func resolveAlias(n *yaml.Node) *yaml.Node {
334		for n.Kind == yaml.AliasNode && n.Alias != nil {
335			n = n.Alias
336		}
337		return n
338	}
339	
340	// yamlScalar renders one YAML scalar node as a raw config value: strings
341	// are kept verbatim, booleans are canonicalized to "true" or "false",
342	// numbers become decimal text, and null is reported via isNull.
343	func yamlScalar(n *yaml.Node) (raw string, isNull bool, err error) {
344		switch n.Tag {
345		case "!!null":
346			return "", true, nil
347		case "!!bool":
348			var b bool
349			if err := n.Decode(&b); err != nil {
350				return "", false, fmt.Errorf("invalid boolean %q", n.Value)
351			}
352			return strconv.FormatBool(b), false, nil
353		case "!!int", "!!float":
354			var v any
355			if err := n.Decode(&v); err != nil {
356				return "", false, fmt.Errorf("invalid number %q", n.Value)
357			}
358			switch num := v.(type) {
359			case int:
360				return strconv.Itoa(num), false, nil
361			case int64:
362				return strconv.FormatInt(num, 10), false, nil
363			case uint64:
364				return strconv.FormatUint(num, 10), false, nil
365			case float64:
366				return strconv.FormatFloat(num, 'f', -1, 64), false, nil
367			default:
368				return "", false, fmt.Errorf("invalid number %q", n.Value)
369			}
370		default:
371			// !!str and any other scalar tag (e.g. timestamps) keep the
372			// source text verbatim.
373			return n.Value, false, nil
374		}
375	}
376	
377	// decimalText renders a JSON number as decimal text. Integers are kept
378	// verbatim; fractional and exponent forms are expanded (1e3 becomes
379	// "1000", 1.50 becomes "1.5").
380	func decimalText(s string) (string, error) {
381		if isIntegerText(s) {
382			return s, nil
383		}
384		f, _, err := big.ParseFloat(s, 10, 256, big.ToNearestEven)
385		if err != nil {
386			return "", err
387		}
388		return f.Text('f', -1), nil
389	}
390	
391	// isIntegerText reports whether s is a plain decimal integer.
392	func isIntegerText(s string) bool {
393		if s == "" {
394			return false
395		}
396		if s[0] == '-' || s[0] == '+' {
397			s = s[1:]
398		}
399		if s == "" {
400			return false
401		}
402		for i := 0; i < len(s); i++ {
403			if s[i] < '0' || s[i] > '9' {
404				return false
405			}
406		}
407		return true
408	}
